sys_script_include.script:
gs.include( "ETN_Utils_Framework" );


var ETN_Class_cmdb_ci_service = x_gamlp_obj_frwk.ETN_Class.create();

ETN_Class_cmdb_ci_service.FILTER_REQUIRES = function( arr ) { return arr.filter( function( relation ) { return relation.Type.SysId == "a290f4ef477bce1097744049116d4363"; }, this ); };

ETN_Class_cmdb_ci_service.prototype = 
	x_gamlp_obj_frwk.ETN_Object.extendsObject( x_gamlp_obj_frwk.ETN_Class_cmdb_ci_service, {

	offerings: function( filter, order ) {
		return ETN_Class_service_offering.QUERY_WHERE_PARENT( this, filter ).getCollection( order );
	},

	requiredDependencies: function( filter ) {
		return this.ciChildRelations( ETN_Class_cmdb_ci_service.FILTER_REQUIRES ).map( function( relation ) { return relation.Child; }, this );
	},

	generateApprouvers: function( previousApprouval, recursive ) {
		recursive = ( typeof recursive === "undefined" ? false : recursive );
		previousApprouval = ( typeof previousApprouval !== "undefined" ? previousApprouval : new Approuval() );

		var approuversSysId = [];

		if ( this.XGamlpIdmLcAccessApprovalProcess == "owner_or_delegate" ) {
			if ( this.OwnedBy != "" && this.OwnedBy.Active ) {
				approuversSysId.push( this.OwnedBy.SysId.toString() );
			}

			if ( this.UDelegue != "" && this.UDelegue.Active ) {
				approuversSysId.push( this.UDelegue.SysId.toString() );

			} else if ( this.Parent != "" && this.Parent.UDelegue != "" && this.Parent.UDelegue.Active ) {
				approuversSysId.push( this.Parent.UDelegue.SysId.toString() );
			}

			if ( approuversSysId.length > 0 ) {
				previousApprouval.add( "Approbation du propriétaire", "ApprovesRejectsAnyU[" + approuversSysId.join( "," ).toString() + "]" );
			}

		} else if ( this.XGamlpIdmLcAccessApprovalProcess == "delegate" ) {
			if ( this.UDelegue != "" && this.UDelegue.Active ) {
				approuversSysId.push( this.UDelegue.SysId.toString() );

			} else if ( this.Parent != "" && this.Parent.UDelegue != "" && this.Parent.UDelegue.Active ) {
				approuversSysId.push( this.Parent.UDelegue.SysId.toString() );
			}

			if ( approuversSysId.length > 0 ) {
				previousApprouval.add( "Approbation du propriétaire", "ApprovesRejectsAnyU[" + approuversSysId.join( "," ).toString() + "]" );
			}

		} else if ( this.XGamlpIdmLcAccessApprovalProcess == "support_group" ) {
			if ( this.SupportGroup != "" && this.SupportGroup.Active ) {
				approuversSysId.push( this.UDelegue.SysId.toString() );

			} else if ( this.Parent != "" && this.Parent.SupportGroup != "" && this.Parent.SupportGroup.Active ) {
				approuversSysId.push( this.Parent.SupportGroup.SysId.toString() );
			}

			if ( approuversSysId.length > 0 ) {
				previousApprouval.add( "Approbation du groupe propriétaire", "ApprovesRejectsAnyG[" + approuversSysId.join( "," ).toString() + "]" );
			}
		}


		if ( recursive ) {
			this.Offerings().forEach( function( offering ) {
				previousApprouval = offering.generateApprouvers( previousApprouval, recursive );
			}, this );
		}

		return previousApprouval;
	},

	get type_scope() { return gs.getCurrentScopeName(); },
    type: 'ETN_Class_cmdb_ci_service'
} );
